425	func TestVerifyAuditDetectsTampering(t *testing.T) {
426		s := NewStore()
427		s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
428		s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))
429		s.Publish("acme", 1, nil)
430		s.Decide("acme", request("acme", "u2", "r1", "org/a", "read"))
431	
432		good, cp, err := s.AuditExport("acme", 0)
433		if err != nil {
434			t.Fatal(err)
435		}
436		check := func(name string, mutate func([]AuditRecord) []AuditRecord, checkpoint Checkpoint) {
437			t.Helper()
438			recs := append([]AuditRecord(nil), good...)
439			recs = mutate(recs)
440			if err := VerifyAudit("acme", recs, checkpoint); err == nil {
441				t.Fatalf("%s: tampered records verified", name)
442			}
443		}
444	
445		// Modify a field deep inside a payload.
446		check("field change", func(r []AuditRecord) []AuditRecord {
447			r[1].Decision.Decision.Allowed = !r[1].Decision.Decision.Allowed
448			return r
449		}, cp)
450		check("policy change", func(r []AuditRecord) []AuditRecord {
451			r[0].Change.Policies[0].Effect = EffectDeny
452			return r
453		}, cp)
454		// Delete a middle record, keep the tail.
455		check("delete middle", func(r []AuditRecord) []AuditRecord {
456			return []AuditRecord{r[0], r[2], r[3]}
457		}, cp)
458		// Delete the tail while still claiming the original checkpoint.
459		check("delete tail", func(r []AuditRecord) []AuditRecord { return r[:2] }, cp)
460		// A genuine prefix export with its matching checkpoint verifies.
461		prefix, prefixCP, err := s.AuditExport("acme", 2)
462		if err != nil {
463			t.Fatal(err)
464		}
465		if err := VerifyAudit("acme", prefix, prefixCP); err != nil {
466			t.Fatalf("prefix export must verify: %v", err)
467		}
468		// Swap order.
469		check("swap order", func(r []AuditRecord) []AuditRecord {
470			r[0], r[1] = r[1], r[0]
471			return r
472		}, cp)
473		// Claim a foreign checkpoint fingerprint.
474		check("foreign checkpoint", func(r []AuditRecord) []AuditRecord { return r },
475			Checkpoint{Org: "acme", EndSeq: 4, Fingerprint: genesisFingerprint("globex")})
476		// Wrong end sequence in the checkpoint.
477		check("wrong length", func(r []AuditRecord) []AuditRecord { return r[:3] }, cp)
478	}
