564	func TestConcurrentOperationsKeepChainConsistent(t *testing.T) {
565		s := NewStore()
566		const publishers = 8
567		const deciders = 8
568		const perDecider = 25
569		var wg sync.WaitGroup
570		var successfulChanges int64
571		var decides int64
572	
573		for i := 0; i < publishers; i++ {
574			wg.Add(1)
575			go func(id int) {
576				defer wg.Done()
577				for j := 0; j < 6; j++ {
578					expected := s.CurrentVersion("acme")
579					pol := []Policy{{
580						ID:      fmt.Sprintf("p-%d-%d", id, j),
581						Subject: fmt.Sprintf("u%d", id),
582						Action:  "read",
583						Scope:   "org/a",
584						Effect:  EffectAllow,
585					}}
586					if v, err := s.Publish("acme", expected, pol); err == nil {
587						atomic.AddInt64(&successfulChanges, 1)
588						_ = v
589						continue
590					}
591					// On conflict, attempt a rollback to a known version.
592					if v, err := s.Rollback("acme", s.CurrentVersion("acme"), 1); err == nil {
593						atomic.AddInt64(&successfulChanges, 1)
594						_ = v
595					}
596				}
597			}(i)
598		}
599		for i := 0; i < deciders; i++ {
600			wg.Add(1)
601			go func(id int) {
602				defer wg.Done()
603				for j := 0; j < perDecider; j++ {
604					s.Decide("acme", request("acme", fmt.Sprintf("u%d", id), "r1", "org/a", "read"))
605					atomic.AddInt64(&decides, 1)
606				}
607			}(i)
608		}
609		wg.Wait()
610	
611		recs, cp, err := s.AuditExport("acme", 0)
612		if err != nil {
613			t.Fatal(err)
614		}
615		// No missing record: one entry per successful change plus every Decide.
616		want := int(successfulChanges) + int(decides)
617		if len(recs) != want {
618			t.Fatalf("records = %d, want %d (changes %d, decides %d)", len(recs), want, successfulChanges, decides)
619		}
620		if err := VerifyAudit("acme", recs, cp); err != nil {
621			t.Fatalf("chain invalid under concurrency: %v", err)
622		}
623		if int64(s.CurrentVersion("acme")) != successfulChanges {
624			t.Fatalf("version %d != successful changes %d", s.CurrentVersion("acme"), successfulChanges)
625		}
626	
627		// No duplicate sequences and every decision matches its recorded version.
628		seen := map[int]bool{}
629		changesAtVersion := map[int]*AuditRecord{}
630		for i := range recs {
631			r := &recs[i]
632			if r.Seq != i+1 {
633				t.Fatalf("gap/dup in sequence at index %d: seq %d", i, r.Seq)
634			}
635			if seen[r.Seq] {
636				t.Fatalf("duplicate sequence %d", r.Seq)
637			}
638			seen[r.Seq] = true
639			if r.Kind == AuditPolicyChange {
640				changesAtVersion[r.Change.Version] = r
641			}
642		}
643		for i := range recs {
644			r := &recs[i]
645			if r.Kind != AuditDecision || r.Decision.Decision.Version == 0 {
646				continue
647			}
648			v := r.Decision.Decision.Version
649			ch, ok := changesAtVersion[v]
650			if !ok {
651				t.Fatalf("decision at seq %d used version %d with no change record", r.Seq, v)
652			}
653			// The decision must be exactly what that version's policies produce.
654			got := evaluate(r.Decision.Request, ch.Change.Policies, v)
655			if !reflect.DeepEqual(got, r.Decision.Decision) {
656				t.Fatalf("seq %d decision %+v does not match version %d evaluation %+v",
657					r.Seq, r.Decision.Decision, v, got)
658			}
659		}
660	}
