func TestRecheckDecisionReplaysRecordedVersion(t *testing.T) {
	s := NewStore()
	v1, _ := s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
	req := request("acme", "u1", "r1", "org/a", "read")
	original := s.Decide("acme", req) // seq 2, version 1, allowed
	deniedReq := request("acme", "u2", "r1", "org/a", "read")
	origDeny := s.Decide("acme", deniedReq) // seq 3, denied by default

	// Later publish removes the access, then a rollback happens.
	s.Publish("acme", 1, nil)
	s.Rollback("acme", 2, 1)
	// Current version is 3. A fresh decide for u2 would still deny; u1 allowed.
	// Rechecking seq 2 must reproduce the version-1 allow.
	got, err := s.RecheckDecision("acme", 2)
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(got, original) || got.Version != v1 {
		t.Fatalf("recheck = %+v, want original %+v (version %d)", got, original, v1)
	}
	gotDeny, err := s.RecheckDecision("acme", 3)
	if err != nil || !reflect.DeepEqual(gotDeny, origDeny) {
		t.Fatalf("recheck deny = %+v, %v, want %+v", gotDeny, err, origDeny)
	}

	// A no-published-version denial rechecks as the same denial.
	s.Decide("blank", request("blank", "u1", "r1", "org/a", "read"))
	if d, err := s.RecheckDecision("blank", 1); err != nil || d.Allowed ||
		d.Reason != "organization has no published version" {
		t.Fatalf("recheck no-version denial = %+v, %v", d, err)
	}
	// An envelope rejection rechecks through the same envelope checks.
	mismatch := request("acme", "u1", "r1", "org/a", "read")
	mismatch.SubjectOrg = "globex"
	s.Decide("acme", mismatch) // publish=seq1, decides=2,3,6; publish=4; rollback=5
	if d, err := s.RecheckDecision("acme", 6); err != nil || d.Allowed || d.Reason != "organization mismatch" {
		t.Fatalf("recheck mismatch = %+v, %v", d, err)
	}

	// Distinguishable errors.
	if _, err := s.RecheckDecision("acme", 1); !errors.Is(err, ErrAuditNotADecision) {
		t.Fatalf("recheck policy_change err = %v", err)
	}
	if _, err := s.RecheckDecision("acme", 99); !errors.Is(err, ErrAuditNotFound) {
		t.Fatalf("recheck missing seq err = %v", err)
	}
	if _, err := s.RecheckDecision("ghost", 1); !errors.Is(err, ErrAuditNotFound) {
		t.Fatalf("recheck unknown org err = %v", err)
	}
}

func TestConcurrentOperationsKeepChainConsistent(t *testing.T) {
	s := NewStore()
	const publishers = 8
	const deciders = 8
	const perDecider = 25
	var wg sync.WaitGroup
	var successfulChanges int64
	var decides int64

	for i := 0; i < publishers; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			for j := 0; j < 6; j++ {
				expected := s.CurrentVersion("acme")
				pol := []Policy{{
					ID:      fmt.Sprintf("p-%d-%d", id, j),
					Subject: fmt.Sprintf("u%d", id),
					Action:  "read",
					Scope:   "org/a",
					Effect:  EffectAllow,
				}}
				if v, err := s.Publish("acme", expected, pol); err == nil {
					atomic.AddInt64(&successfulChanges, 1)
					_ = v
					continue
				}
				// On conflict, attempt a rollback to a known version.
				if v, err := s.Rollback("acme", s.CurrentVersion("acme"), 1); err == nil {
					atomic.AddInt64(&successfulChanges, 1)
					_ = v
				}
			}
		}(i)
	}
	for i := 0; i < deciders; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			for j := 0; j < perDecider; j++ {
				s.Decide("acme", request("acme", fmt.Sprintf("u%d", id), "r1", "org/a", "read"))
				atomic.AddInt64(&decides, 1)
			}
		}(i)
	}
	wg.Wait()

	recs, cp, err := s.AuditExport("acme", 0)
	if err != nil {
		t.Fatal(err)
	}
	// No missing record: one entry per successful change plus every Decide.
	want := int(successfulChanges) + int(decides)
	if len(recs) != want {
		t.Fatalf("records = %d, want %d (changes %d, decides %d)", len(recs), want, successfulChanges, decides)
	}
	if err := VerifyAudit("acme", recs, cp); err != nil {
		t.Fatalf("chain invalid under concurrency: %v", err)
	}
	if int64(s.CurrentVersion("acme")) != successfulChanges {
		t.Fatalf("version %d != successful changes %d", s.CurrentVersion("acme"), successfulChanges)
	}

	// No duplicate sequences and every decision matches its recorded version.
	seen := map[int]bool{}
	changesAtVersion := map[int]*AuditRecord{}
	for i := range recs {
		r := &recs[i]
		if r.Seq != i+1 {
			t.Fatalf("gap/dup in sequence at index %d: seq %d", i, r.Seq)
		}
		if seen[r.Seq] {
			t.Fatalf("duplicate sequence %d", r.Seq)
		}
		seen[r.Seq] = true
		if r.Kind == AuditPolicyChange {
			changesAtVersion[r.Change.Version] = r
		}
	}
	for i := range recs {
		r := &recs[i]
		if r.Kind != AuditDecision || r.Decision.Decision.Version == 0 {
			continue
		}
		v := r.Decision.Decision.Version
		ch, ok := changesAtVersion[v]
		if !ok {
			t.Fatalf("decision at seq %d used version %d with no change record", r.Seq, v)
		}
		// The decision must be exactly what that version's policies produce.
		got := evaluate(r.Decision.Request, ch.Change.Policies, v)
		if !reflect.DeepEqual(got, r.Decision.Decision) {
			t.Fatalf("seq %d decision %+v does not match version %d evaluation %+v",
				r.Seq, r.Decision.Decision, v, got)
		}
	}
}

package darksafe

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"reflect"
	"strings"
	"testing"
	"unicode/utf8"
)

// invalidByte is a lone byte that is never valid UTF-8 on its own.
const invalidByte = "\xff"

// anotherInvalidByte renders identically under JSON replacement but is a
// different raw byte.
const anotherInvalidByte = "\xfe"

// replacementRune is a genuine U+FFFD code point: valid UTF-8, unlike the
// lone invalid bytes.
const replacementRune = string(rune(0xFFFD))

// legacyJSONFingerprint is the exact fingerprint algorithm used before
// the raw-content integrity fix: encoding/json over the envelope. Tests
// use it to prove valid-UTF-8 records keep byte-identical fingerprints.
func legacyJSONFingerprint(r *AuditRecord) string {
	b, err := json.Marshal(&hashEnvelope{
		Org:             r.Org,
		Seq:             r.Seq,
		Kind:            r.Kind,
		Change:          r.Change,
		Decision:        r.Decision,
		PrevFingerprint: r.PrevFingerprint,
	})
	if err != nil {
		panic(err)
	}
	sum := sha256.Sum256(b)
	return hex.EncodeToString(sum[:])
}

// cloneExportedRecords deep-copies a record set so mutating any string
// field or roles/matched/policies slice in the copy never reaches the
// original. encoding/json cannot be used for this: it would "repair" the
// invalid bytes under test.
func cloneExportedRecords(in []AuditRecord) []AuditRecord {
	out := make([]AuditRecord, len(in))
	for i, r := range in {
		cp := r
		if r.Change != nil {
			c := *r.Change
			if r.Change.Policies != nil {
				c.Policies = append([]Policy(nil), r.Change.Policies...)
			}
			cp.Change = &c
		}
		if r.Decision != nil {
			d := *r.Decision
			if r.Decision.Request.Subject.Roles != nil {
				d.Request.Subject.Roles = append([]string(nil), r.Decision.Request.Subject.Roles...)
			}
			if r.Decision.Decision.Matched != nil {
				d.Decision.Matched = append([]string(nil), r.Decision.Decision.Matched...)
			}
			cp.Decision = &d
		}
		out[i] = cp
	}
	return out
}

// TestInvalidUTF8IsAcceptedAndPreservedByteForByte drives the live API
// with strings carrying invalid UTF-8 in every policy and request string
// reachable through the public surface. Acceptance must be unchanged, no
// byte may be deleted, replaced or normalized, and query/export/offline
// review must observe the exact submitted bytes.
func TestInvalidUTF8IsAcceptedAndPreservedByteForByte(t *testing.T) {
	s := NewStore()
	submitted := Policy{
		ID:      "策" + invalidByte + "略",
		Subject: "用" + invalidByte + "戶",
		Action:  "读" + invalidByte,
		Scope:   "org/a/资" + invalidByte + "料",
		Effect:  EffectAllow,
	}
	v, err := s.Publish("acme", 0, []Policy{submitted})
	if err != nil || v != 1 {
		t.Fatalf("publish with invalid UTF-8 = %d, %v; want accepted", v, err)
	}

	req := OrgRequest{
		SubjectOrg:  "acme",
		ResourceOrg: "acme",
		Subject: Subject{
			ID:    "用" + invalidByte + "戶",
			Kind:  "外" + invalidByte + "部",
			Roles: []string{"角" + invalidByte + "色", "普通角色"},
		},
		Resource: Resource{ID: "资" + invalidByte + "源", Scope: submitted.Scope},
		Action:   submitted.Action,
	}
	d := s.Decide("acme", req)
	if !d.Allowed || d.Version != 1 || d.Reason != "matched allow policy" {
		t.Fatalf("decision on invalid-UTF-8 request = %+v", d)
	}
	if want := []string{submitted.ID}; !reflect.DeepEqual(d.Matched, want) {
		t.Fatalf("matched = %q, want byte-exact %q", d.Matched, want)
	}
	if !strings.Contains(d.Matched[0], invalidByte) {
		t.Fatal("invalid byte normalized out of matched policy id")
	}

	// A rollback republishes the invalid-byte content and records it.
	if rv, err := s.Rollback("acme", 1, 1); err != nil || rv != 2 {
		t.Fatalf("rollback = %d, %v", rv, err)
	}
	// A normal record and an invalid-byte record coexist in one export.

